const {chromium}=require('playwright'),fs=require('fs'),os=require('os'),path=require('path'),http=require('http'),assert=require('assert/strict'),{execFileSync}=require('child_process');
const repo=path.resolve(__dirname,'../..'),dir=fs.mkdtempSync(path.join(os.tmpdir(),'sambaadm-search-'));
execFileSync('go',['test','./internal/web','-run','^TestWorkspaceBrowserFixtures$','-count=1'],{cwd:repo,env:{...process.env,SAMBAADM_WEB_FIXTURE_DIR:dir}});
const server=http.createServer((req,res)=>{const p=new URL(req.url,'http://localhost').pathname,file=p.startsWith('/static/')?path.join(repo,'internal/web',p):path.join(dir,'admin-'+p.slice(1)+'.html');if(!fs.existsSync(file)){res.writeHead(404).end();return;}res.setHeader('Content-Type',file.endsWith('.js')?'application/javascript':file.endsWith('.css')?'text/css':'text/html');res.end(fs.readFileSync(file));});
(async()=>{await new Promise(r=>server.listen(0,'127.0.0.1',r));const browser=await chromium.launch({headless:true});try{const page=await browser.newPage({viewport:{width:1440,height:1000}});const errors=[];page.on('pageerror',e=>errors.push(e.message));let modelReads=0;const guid='{11111111-1111-1111-1111-111111111111}';await page.route('**/api/v1/**',async route=>{const u=new URL(route.request().url()),p=u.pathname.slice(7);let result=[];if(p==='/me')result={samAccountName:'ivanova',displayName:'Анна Иванова',mail:'ivanova@example.com',department:'Бухгалтерия',dn:'CN=Анна Иванова,OU=Сотрудники,DC=example,DC=com',revision:'one',groups:[],enabled:true};if(p==='/gpo')result=[{guid,displayName:'Политика сотрудников',source:'ldap'}];if(p==='/directory/tree')result={kind:'domain',label:'example.com',dn:'DC=example,DC=com',children:[]};if(p.endsWith('/alt-settings')){modelReads++;result={scope:u.searchParams.get('scope')||'Machine',version:1,settings:[{id:'example',label:'Настройка службы',category:'Система',state:'not-configured',fields:[]}]};}if(p.endsWith('/drives'))result={revision:'one',version:1,scopes:{Machine:{drives:[]},User:{drives:[]}}};await route.fulfill({json:result});});const base='http://127.0.0.1:'+server.address().port;
await page.goto(base+'/me');await page.getByRole('heading',{name:'Контактные данные',exact:true}).waitFor();await page.screenshot({path:path.join(dir,'profile-desktop.png'),fullPage:true});assert.equal(await page.getByLabel('Телефон',{exact:true}).getAttribute('type'),'tel');await page.getByRole('button',{name:'Найти в домене',exact:true}).click();const search=page.getByRole('dialog');assert(await search.evaluate(e=>e.getBoundingClientRect().width<=650));await page.screenshot({path:path.join(dir,'search-desktop.png'),fullPage:true});await search.getByRole('button',{name:'Закрыть',exact:true}).click();
await page.goto(base+'/gpo');await page.getByRole('button',{name:'Свойства',exact:true}).waitFor();assert.equal(await page.getByRole('button',{name:'Редактор политик',exact:true}).count(),0);assert(await page.locator('tbody tr').first().evaluate(e=>e.getBoundingClientRect().height<100));await page.locator('tbody .row-actions summary').first().click();assert.equal(await page.getByRole('button',{name:'Делегирование LDAP/SYSVOL',exact:true}).count(),1);await page.screenshot({path:path.join(dir,'gpo-menu.png'),fullPage:true});await page.getByRole('button',{name:'Редактор политик',exact:true}).click();const dialog=page.getByRole('dialog');await dialog.getByRole('button',{name:'Конфигурация пользователя',exact:true}).waitFor();assert.equal(await dialog.getByRole('combobox',{name:'Раздел политики',exact:true}).count(),0);await dialog.getByRole('button',{name:'Конфигурация пользователя',exact:true}).click();await dialog.getByRole('button',{name:'Конфигурация компьютера',exact:true}).click();assert.equal(modelReads,2,'switching configurations must reuse both loaded models');await page.screenshot({path:path.join(dir,'policy-tree.png'),fullPage:true});await page.setViewportSize({width:390,height:844});assert.equal(await dialog.evaluate(e=>e.scrollWidth>e.clientWidth),false);await dialog.getByRole('button',{name:'Закрыть окно',exact:true}).click();await page.goto(base+'/me');await page.getByRole('heading',{name:'Контактные данные',exact:true}).waitFor();assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);await page.screenshot({path:path.join(dir,'profile-mobile.png'),fullPage:true});assert.deepEqual(errors,[]);console.log('PASS compact search, profile, grouped GPO actions, simultaneous configurations, no reload on switching, mobile. Screenshots:',dir);}finally{await browser.close();server.close();}})().catch(e=>{console.error(e);server.close();process.exitCode=1;});
